files.style.css:
* { box-sizing: border-box; }
html, body { margin: 0; background: #ffffff; color: #111827; font-family: 'DejaVu Sans', sans-serif; font-size: 15px; line-height: 1.5; }
a { color: inherit; text-decoration: none; }
.bar { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.brand { display: flex; align-items: center; gap: 8px; }
.nav { display: flex; gap: 16px; font-size: 14px; }
.nav a { color: #e5e7eb; }
main { padding: 24px; max-width: 1040px; margin: 0 auto; }
.toolbar { display: flex; gap: 12px; align-items: center; margin: 16px 0; flex-wrap: wrap; }
.search { display: flex; align-items: center; gap: 6px; flex: 1 1 220px; }
.search input { width: 100%; }
button { border: 0; font-family: inherit; font-size: 15px; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; }
input, select { font-family: inherit; font-size: 15px; background: #ffffff; color: #111827; }
.field { display: flex; flex-direction: column; gap: 6px; }
.icon { width: 16px; height: 16px; flex: none; }
.cols { display: grid; grid-template-columns: 2fr 1fr; gap: 24px; }
.table-wrap { overflow-x: auto; }
th { text-align: left; font-size: 13px; color: #4b5563; padding: 8px 12px; }
td { padding: 12px; border-bottom: 1px solid #e5e7eb; }
[data-testid^="status-badge"] { background: #dcfce7; color: #166534; border-radius: 999px; padding: 2px 10px; font-size: 13px; font-weight: 600; }
[data-testid="items-list"] li { display: flex; justify-content: space-between; padding: 12px 16px; border: 1px solid #e5e7eb; border-radius: 8px; }
@media (max-width: 600px) { main { padding: 16px; } .cols { grid-template-columns: 1fr; } .hide-sm { display: none; } }
[data-testid="app-header"] { padding: 16px 24px; background: #111827; color: #f9fafb; }
[data-testid="brand-name"] { font-size: 18px; font-weight: 700; color: #f9fafb; }
[data-testid="brand-icon"] { width: 20px; height: 20px; }
[data-testid="last-updated"] { font-size: 13px; color: #d1d5db; }
[data-testid="page-title-list"] { font-size: 26px; font-weight: 700; color: #111827; margin: 0; }
[data-testid="new-order-btn"] { background: #2952cc; color: #ffffff; border-radius: 8px; height: 40px; padding: 0 16px; font-weight: 600; }
[data-testid="search-input"] { height: 40px; border-radius: 8px; padding: 0 12px; border: 1px solid #9ca3af; }
[data-testid="orders-table"] { border-spacing: 0; width: 100%; }
[data-testid="order-cell"] { padding: 12px; border-bottom: 1px solid #e5e7eb; }
[data-testid="status-badge"] { background: #fef3c7; color: #166534; border-radius: 999px; padding: 2px 10px; font-size: 13px; font-weight: 600; }
[data-testid="summary-card"] { margin-top: 24.4px; padding: 16px; border-radius: 8px; background: #f3f4f6; }
[data-testid="page-title-detail"] { font-size: 26px; font-weight: 700; color: #111827; margin: 0; max-width: 90px; display: inline-block; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; vertical-align: bottom; }
[data-testid="detail-status"] { background: #dbeafe; color: #1e40af; border-radius: 999px; padding: 4px 12px; font-size: 14px; font-weight: 600; }
[data-testid="items-list"] { list-style: none; padding: 0; margin: 16px 0; display: flex; flex-direction: column; gap: 8px; }
[data-testid="item-row"] { display: flex; justify-content: space-between; padding: 12px 16px; border: 1px solid #e5e7eb; border-radius: 8px; }
[data-testid="order-total"] { font-size: 20px; font-weight: 700; color: #111827; }
[data-testid="refund-btn"] { background: #b91c1c; color: #ffffff; border-radius: 8px; height: 40px; padding: 0 16px; font-weight: 600; }
[data-testid="notes-text"] { color: #374151; font-size: 15px; line-height: 24px; }
[data-testid="page-title-form"] { font-size: 26px; font-weight: 700; color: #111827; margin: 0; }
[data-testid="form-fields"] { display: flex; flex-direction: column; gap: 20px; max-width: 560px; }
[data-testid="customer-label"] { font-size: 14px; font-weight: 400; color: #111827; }
[data-testid="customer-input"] { height: 40px; border-radius: 8px; padding: 0 12px; border: 1px solid #9ca3af; }
[data-testid="amount-input"] { height: 40px; border-radius: 8px; padding: 0 12px; border: 1px solid #9ca3af; }
[data-testid="help-text"] { font-size: 13px; color: #b45309; }
[data-testid="submit-btn"] { background: #2952cc; color: #ffffff; border-radius: 8px; height: 44px; padding: 0 20px; font-weight: 600; }
@media (max-width: 600px) {
  [data-testid="app-header"] { padding: 12px 16px; }
  [data-testid="page-title-list"] { font-size: 28px; }
  [data-testid="page-title-detail"] { font-size: 22px; }
  [data-testid="page-title-form"] { font-size: 22px; }
  [data-testid="summary-card"] { padding: 12px; }
  [data-testid="new-order-btn"] { height: 32px; }
}

